package vn.hust.restaurant.view;
import java.awt.*;import java.util.*;import javax.swing.*;import vn.hust.restaurant.config.*;import vn.hust.restaurant.model.UserSession;
public class MainFrame extends JFrame{private final AppContext ctx;private final UserSession session;private final CardLayout cards=new CardLayout();private final JPanel content=new JPanel(cards);private final Map<String,Refreshable> refreshables=new HashMap<>();public MainFrame(AppContext c,UserSession s){super(AppConfig.app("restaurant.name","HTQL Nhà hàng")+" - "+s.fullName()+" ["+s.role()+"]");ctx=c;session=s;setDefaultCloseOperation(EXIT_ON_CLOSE);setSize(1450,850);setLocationRelativeTo(null);build();}
 private void build(){JPanel nav=new JPanel();nav.setLayout(new BoxLayout(nav,BoxLayout.Y_AXIS));nav.setBorder(BorderFactory.createEmptyBorder(10,10,10,10));nav.setPreferredSize(new Dimension(210,0));addPanel(nav,"Tổng quan",new DashboardPanel(ctx));if(session.hasRole("CHU_NHA_HANG","PHUC_VU")){addPanel(nav,"Bàn & gọi món",new TableOrderPanel(ctx,session));addPanel(nav,"Đặt bàn",new ReservationPanel(ctx,session));}if(session.hasRole("CHU_NHA_HANG","DAU_BEP"))addPanel(nav,"Bếp",new KitchenPanel(ctx,session));if(session.hasRole("CHU_NHA_HANG","THU_NGAN"))addPanel(nav,"Thanh toán",new PaymentPanel(ctx,session));if(session.hasRole("CHU_NHA_HANG"))addPanel(nav,"Thực đơn",new MenuPanel(ctx));if(session.hasRole("CHU_NHA_HANG","DAU_BEP"))addPanel(nav,"Kho",new InventoryPanel(ctx,session));if(session.hasRole("CHU_NHA_HANG","THU_NGAN"))addPanel(nav,"Khách hàng",new CustomerPanel(ctx));if(session.hasRole("CHU_NHA_HANG")){addPanel(nav,"Nhân viên",new EmployeePanel(ctx));addPanel(nav,"Báo cáo",new ReportPanel(ctx));}nav.add(Box.createVerticalGlue());JButton logout=new JButton("Đăng xuất");logout.setAlignmentX(Component.CENTER_ALIGNMENT);logout.addActionListener(e->{dispose();new LoginFrame(ctx).setVisible(true);});nav.add(logout);add(nav,BorderLayout.WEST);add(content,BorderLayout.CENTER);cards.first(content);}
 private void addPanel(JPanel nav,String name,JPanel panel){content.add(panel,name);if(panel instanceof Refreshable r)refreshables.put(name,r);JButton b=new JButton(name);b.setMaximumSize(new Dimension(Integer.MAX_VALUE,44));b.setAlignmentX(Component.CENTER_ALIGNMENT);b.addActionListener(e->{cards.show(content,name);Refreshable r=refreshables.get(name);if(r!=null)r.refresh();});nav.add(b);nav.add(Box.createVerticalStrut(6));}
}
